#define DOWNSAMPLE 40.0 //change to 2 or 4
#define ITERATIONS 2

vec4 kawaseBlur(sampler2D tex, vec2 uv, vec2 offset) {
    vec4 color = vec4(0.0);
    for (int i = 0; i < ITERATIONS; i++) {
        color += texture(tex, uv + offset * vec2(1, 1));
        color += texture(tex, uv + offset * vec2(-1, 1));
        color += texture(tex, uv + offset * vec2(1, -1));
        color += texture(tex, uv + offset * vec2(-1, -1));
        uv += offset;
    }
    return color / float(ITERATIONS * 4);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord / iResolution.xy;

    //  Downsampling
    vec2 downUV = floor(fragCoord / DOWNSAMPLE) * DOWNSAMPLE / iResolution.xy;


    vec2 pixelSize = vec2(8.0) / iResolution.xy;
    vec4 blurred = kawaseBlur(iChannel0, downUV, pixelSize * 0.5);
    //(pixelSize * 0.25, 0.75) control
    fragColor = blurred;
}

